<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>MedBook — Find and Book Top Doctors Instantly</title>
  <meta name="description" content="Search doctors, dentists, and specialists by specialty, condition, location, and insurance. Read verified reviews and book same-day appointments in minutes." />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root {
      --primary: #0066ff;
      --primary-dark: #0052cc;
      --teal: #12b3a8;
      --teal-dark: #0e938a;
      --text: #16324f;
      --muted: #5f738a;
      --surface: #ffffff;
      --surface-soft: #f4f8fc;
      --border: #dbe7f3;
      --shadow: 0 10px 30px rgba(17, 64, 117, 0.09);
      --radius-lg: 18px;
      --radius-md: 12px;
      --radius-sm: 10px;
      --maxw: 1160px;
    }

    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; }
    body {
      font-family: 'Inter', system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
      color: var(--text);
      background: linear-gradient(180deg, #ffffff 0%, #f8fbff 35%, #ffffff 100%);
      line-height: 1.55;
    }

    a { color: inherit; text-decoration: none; }
    img, svg { display: block; max-width: 100%; }

    .container {
      width: min(var(--maxw), calc(100% - 2rem));
      margin-inline: auto;
    }

    .section { padding: 4rem 0; }
    .section.soft { background: var(--surface-soft); }

    .topbar {
      position: sticky;
      top: 0;
      z-index: 60;
      backdrop-filter: blur(8px);
      background: rgba(255,255,255,0.92);
      border-bottom: 1px solid rgba(219, 231, 243, 0.7);
    }

    .nav {
      min-height: 74px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: .6rem;
      font-weight: 800;
      font-size: 1.25rem;
      letter-spacing: -.02em;
      color: var(--primary-dark);
    }

    .logo-badge {
      width: 34px;
      height: 34px;
      border-radius: 10px;
      display: grid;
      place-items: center;
      color: #fff;
      background: linear-gradient(135deg, var(--primary), #4a8dff);
      box-shadow: 0 8px 20px rgba(0, 102, 255, .3);
      font-weight: 700;
      font-size: .95rem;
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 1.1rem;
      color: var(--muted);
      font-weight: 600;
    }

    .nav-links a {
      padding: .55rem .8rem;
      border-radius: 10px;
      transition: .2s ease;
    }

    .nav-links a:hover,
    .nav-links a:focus-visible {
      color: var(--primary-dark);
      background: #e9f1ff;
      outline: none;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: .45rem;
      border: 0;
      font-weight: 700;
      letter-spacing: .01em;
      border-radius: 12px;
      min-height: 46px;
      padding: .68rem 1rem;
      cursor: pointer;
      transition: transform .18s ease, box-shadow .18s ease, background .2s ease;
      text-decoration: none;
    }

    .btn:focus-visible { outline: 3px solid #97bbff; outline-offset: 2px; }
    .btn:hover { transform: translateY(-1px); }

    .btn-primary { background: var(--primary); color: #fff; box-shadow: 0 10px 24px rgba(0, 102, 255, .25); }
    .btn-primary:hover { background: var(--primary-dark); }
    .btn-secondary { background: var(--teal); color: #fff; box-shadow: 0 10px 24px rgba(18, 179, 168, .25); }
    .btn-secondary:hover { background: var(--teal-dark); }
    .btn-ghost { background: #eff5ff; color: var(--primary-dark); }

    .mobile-menu-btn {
      display: none;
      width: 44px;
      height: 44px;
      border-radius: 12px;
      border: 1px solid var(--border);
      background: #fff;
      color: var(--primary-dark);
      cursor: pointer;
    }

    .hero {
      padding: 4.75rem 0 2.6rem;
      position: relative;
      overflow: hidden;
    }

    .hero-grid {
      display: grid;
      grid-template-columns: 1.05fr .95fr;
      gap: 2rem;
      align-items: center;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: .45rem;
      padding: .4rem .7rem;
      border-radius: 999px;
      background: #e9f3ff;
      color: var(--primary-dark);
      font-weight: 700;
      font-size: .84rem;
      margin-bottom: 1rem;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 4vw, 3.35rem);
      line-height: 1.08;
      letter-spacing: -.03em;
      max-width: 14ch;
    }

    .hero p {
      margin: 1rem 0 1.6rem;
      color: var(--muted);
      font-size: 1.05rem;
      max-width: 55ch;
    }

    .hero-cards {
      background: #fff;
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow);
      padding: 1.2rem;
      display: grid;
      gap: .9rem;
    }

    .hero-chip-row {
      display: flex;
      gap: .65rem;
      flex-wrap: wrap;
    }

    .chip {
      border-radius: 999px;
      font-weight: 600;
      color: #2a527b;
      background: #f0f6ff;
      padding: .4rem .75rem;
      font-size: .84rem;
    }

    .stat-grid {
      margin-top: 2.2rem;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: .9rem;
    }

    .stat {
      background: #fff;
      border: 1px solid var(--border);
      border-radius: 14px;
      padding: .95rem .9rem;
      box-shadow: var(--shadow);
    }

    .stat strong {
      display: block;
      color: var(--primary-dark);
      font-size: 1.1rem;
      line-height: 1.2;
      margin-bottom: .25rem;
    }

    .stat span {
      display: block;
      color: var(--muted);
      font-size: .88rem;
      line-height: 1.35;
    }

    .search-wrap {
      margin-top: -1rem;
      position: relative;
      z-index: 20;
    }

    .search-box {
      background: #fff;
      border: 1px solid var(--border);
      border-radius: 22px;
      box-shadow: 0 24px 50px rgba(18, 59, 108, 0.15);
      padding: 1rem;
    }

    .search-head {
      margin: .3rem .2rem .8rem;
      font-weight: 700;
      color: var(--primary-dark);
    }

    .search-form {
      display: grid;
      grid-template-columns: minmax(0, 1.4fr) minmax(0, .9fr) auto;
      gap: .8rem;
      align-items: end;
    }

    .field { position: relative; }

    .field label {
      display: block;
      margin: 0 0 .4rem .1rem;
      font-size: .86rem;
      color: #456482;
      font-weight: 600;
    }

    .input {
      width: 100%;
      min-height: 52px;
      border: 1px solid #c8d9ea;
      border-radius: 14px;
      padding: 0 .95rem;
      font-size: 1rem;
      color: var(--text);
      background: #fff;
      transition: border-color .18s ease, box-shadow .18s ease;
    }

    .input:focus {
      outline: none;
      border-color: #76a7ff;
      box-shadow: 0 0 0 3px #d8e8ff;
    }

    .suggestions {
      position: absolute;
      left: 0;
      right: 0;
      top: calc(100% + .45rem);
      background: #fff;
      border: 1px solid var(--border);
      border-radius: 14px;
      box-shadow: var(--shadow);
      padding: .35rem;
      display: none;
      max-height: 260px;
      overflow: auto;
      z-index: 40;
    }

    .suggestion {
      width: 100%;
      text-align: left;
      background: transparent;
      border: 0;
      border-radius: 10px;
      padding: .65rem .7rem;
      display: flex;
      justify-content: space-between;
      align-items: center;
      cursor: pointer;
      font-size: .95rem;
      color: #244b73;
    }

    .suggestion span { color: #6d88a4; font-size: .82rem; }
    .suggestion:hover, .suggestion:focus-visible { background: #eef5ff; outline: none; }

    .grid-3 {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1rem;
    }

    .card {
      background: #fff;
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow);
    }

    .specialty-card {
      padding: 1.1rem;
      display: flex;
      gap: .9rem;
      align-items: center;
      transition: .2s ease;
      min-height: 96px;
    }

    .specialty-card:hover { transform: translateY(-2px); border-color: #b8d2ee; }

    .icon {
      width: 46px;
      height: 46px;
      border-radius: 12px;
      display: grid;
      place-items: center;
      background: linear-gradient(135deg, #ebf3ff, #dff7f4);
      color: var(--primary-dark);
      flex-shrink: 0;
    }

    .specialty-card h3 {
      margin: 0;
      font-size: 1.02rem;
      letter-spacing: -.01em;
    }

    .specialty-card p {
      margin: .2rem 0 0;
      color: var(--muted);
      font-size: .9rem;
    }

    .section-title {
      margin: 0 0 .55rem;
      font-size: clamp(1.5rem, 3vw, 2rem);
      letter-spacing: -.02em;
    }

    .section-copy {
      margin: 0 0 1.5rem;
      color: var(--muted);
      max-width: 65ch;
    }

    .steps {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1rem;
    }

    .step {
      padding: 1.2rem;
      border-radius: var(--radius-lg);
      border: 1px solid var(--border);
      background: #fff;
      box-shadow: var(--shadow);
    }

    .step-num {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      display: grid;
      place-items: center;
      background: #eaf2ff;
      color: var(--primary-dark);
      font-weight: 800;
      margin-bottom: .75rem;
    }

    .testimonial {
      padding: 1.2rem;
      min-height: 190px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
    }

    .testimonial blockquote {
      margin: 0;
      color: #305579;
      font-size: .98rem;
    }

    .testimonial cite {
      margin-top: .9rem;
      color: var(--muted);
      font-style: normal;
      font-size: .88rem;
      font-weight: 600;
    }

    .app-promo {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 1.2rem;
      align-items: center;
      padding: 1.5rem;
      border-radius: 22px;
      background: linear-gradient(135deg, #0f5be6, #0ea59a);
      color: #fff;
      box-shadow: 0 22px 40px rgba(0, 65, 125, 0.25);
    }

    .app-promo h3 { margin: 0 0 .35rem; font-size: clamp(1.2rem, 2.6vw, 1.7rem); }
    .app-promo p { margin: 0; color: #e8f5ff; }
    .store-buttons { display: flex; gap: .7rem; flex-wrap: wrap; }

    .store {
      background: rgba(255,255,255,0.16);
      border: 1px solid rgba(255,255,255,0.35);
      color: #fff;
      min-height: 44px;
      padding: .5rem .85rem;
      border-radius: 12px;
      font-weight: 700;
    }

    footer {
      background: #0e2240;
      color: #d7e5f8;
      padding: 3rem 0 2rem;
      margin-top: 4rem;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1.2rem;
    }

    .footer-col h4 { margin: 0 0 .65rem; color: #fff; font-size: .97rem; }
    .footer-col a { display: block; color: #d7e5f8; margin: .33rem 0; font-size: .9rem; }
    .footer-col a:hover { color: #fff; }
    .copyright {
      margin-top: 1.6rem;
      padding-top: 1rem;
      border-top: 1px solid rgba(255,255,255,0.18);
      font-size: .87rem;
      color: #bdd2ed;
    }

    .drawer {
      position: fixed;
      inset: 0 0 0 auto;
      width: min(82vw, 320px);
      background: #fff;
      border-left: 1px solid var(--border);
      box-shadow: -10px 0 28px rgba(10, 44, 77, 0.14);
      padding: 1.2rem;
      transform: translateX(100%);
      transition: transform .25s ease;
      z-index: 80;
    }

    .drawer.open { transform: translateX(0%); }
    .drawer a { display: block; padding: .8rem; border-radius: 10px; font-weight: 600; color: #2a5078; }
    .drawer a:hover { background: #eef5ff; }
    .backdrop {
      position: fixed;
      inset: 0;
      background: rgba(10, 34, 62, 0.35);
      opacity: 0;
      pointer-events: none;
      transition: opacity .25s ease;
      z-index: 70;
    }
    .backdrop.show { opacity: 1; pointer-events: auto; }

    @media (max-width: 1024px) {
      .hero-grid { grid-template-columns: 1fr; }
      .stat-grid { grid-template-columns: repeat(2, 1fr); }
      .grid-3, .steps, .footer-grid { grid-template-columns: repeat(2, 1fr); }
      .search-form { grid-template-columns: 1fr; }
      .search-form .btn { width: 100%; }
      .app-promo { grid-template-columns: 1fr; }
    }

    @media (max-width: 760px) {
      .nav-links { display: none; }
      .mobile-menu-btn { display: inline-grid; place-items: center; }
      .section { padding: 3rem 0; }
      .hero { padding-top: 3.5rem; }
      .grid-3, .steps, .footer-grid, .stat-grid { grid-template-columns: 1fr; }
      .search-box { border-radius: 16px; }
      h1 { font-size: clamp(1.85rem, 9vw, 2.5rem); }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { animation: none !important; transition: none !important; }
    }
  </style>
</head>
<body>
  <header class="topbar" id="top">
    <div class="container nav">
      <a href="index.html" class="logo" aria-label="MedBook home">
        <span class="logo-badge">M</span>
        <span>MedBook</span>
      </a>
      <nav class="nav-links" aria-label="Primary">
        <a href="#specialties">Browse</a>
        <a href="#footer">Help</a>
        <a href="#">Log In</a>
        <a class="btn btn-primary" href="#" style="min-height:40px;padding:.45rem .8rem;">Sign Up</a>
      </nav>
      <button class="mobile-menu-btn" aria-label="Open menu" aria-expanded="false" aria-controls="mobile-drawer" id="mobile-menu-toggle">
        <svg width="22" height="22" viewBox="0 0 24 24" fill="none" aria-hidden="true">
          <path d="M4 7H20M4 12H20M4 17H20" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
        </svg>
      </button>
    </div>
  </header>

  <main>
    <section class="hero">
      <div class="container hero-grid">
        <div>
          <span class="eyebrow">✨ Trusted by millions of patients</span>
          <h1>Find and book top doctors instantly</h1>
          <p>An online healthcare marketplace that helps you discover local doctors, dentists, and specialists. Compare verified reviews, filter by insurance, and book same-day appointments in minutes.</p>
          <a class="btn btn-secondary" href="#search">Start your search</a>

          <div class="stat-grid" aria-label="Platform stats" id="stats">
            <article class="stat">
              <strong>6M+ reviews</strong>
              <span>Millions of verified patient reviews</span>
            </article>
            <article class="stat">
              <strong>18k+ providers</strong>
              <span>Thousands of providers across specialties</span>
            </article>
            <article class="stat">
              <strong>Same-day care</strong>
              <span>Appointments available as soon as today</span>
            </article>
            <article class="stat">
              <strong>Always free</strong>
              <span>MedBook is free for patients</span>
            </article>
          </div>
        </div>

        <aside class="hero-cards" aria-label="Highlights">
          <div class="hero-chip-row">
            <span class="chip">Primary Care</span>
            <span class="chip">Dentist</span>
            <span class="chip">Dermatologist</span>
          </div>
          <div class="card" style="padding:1rem; border-radius:14px;">
            <strong style="display:block; margin-bottom:.35rem;">Search by name, specialty, or condition</strong>
            <span style="color:var(--muted); font-size:.92rem;">From annual checkups to urgent visits, quickly find the right provider near you.</span>
          </div>
          <div class="card" style="padding:1rem; border-radius:14px;">
            <strong style="display:block; margin-bottom:.35rem;">Book in under 2 minutes</strong>
            <span style="color:var(--muted); font-size:.92rem;">Real-time slots and transparent availability help you book with confidence.</span>
          </div>
        </aside>
      </div>
    </section>

    <section class="search-wrap" id="search">
      <div class="container">
        <div class="search-box">
          <div class="search-head">Search doctors, specialties, and conditions</div>
          <form class="search-form" id="search-form" action="search-results.html" method="get">
            <div class="field">
              <label for="query">What are you looking for?</label>
              <input id="query" class="input" name="q" type="text" placeholder="e.g., Dentist, Dermatologist, back pain" autocomplete="off" aria-autocomplete="list" aria-controls="suggestions" aria-expanded="false" />
              <div class="suggestions" id="suggestions" role="listbox" aria-label="Search suggestions"></div>
            </div>
            <div class="field">
              <label for="location">Location</label>
              <input id="location" class="input" name="location" type="text" value="New York, NY" />
            </div>
            <button class="btn btn-primary" type="submit">Find Care</button>
          </form>
        </div>
      </div>
    </section>

    <section class="section" id="specialties">
      <div class="container">
        <h2 class="section-title">Popular specialties</h2>
        <p class="section-copy">Browse common care types to quickly find providers that match your needs.</p>
        <div class="grid-3">
          <a class="card specialty-card" href="search-results.html?specialty=Primary%20Care">
            <div class="icon">🩺</div>
            <div><h3>Primary Care</h3><p>Routine checkups and preventive care</p></div>
          </a>
          <a class="card specialty-card" href="search-results.html?specialty=Dentist">
            <div class="icon">🦷</div>
            <div><h3>Dentist</h3><p>Cleanings, cavities, and oral health</p></div>
          </a>
          <a class="card specialty-card" href="search-results.html?specialty=Dermatologist">
            <div class="icon">🧴</div>
            <div><h3>Dermatologist</h3><p>Skin, hair, and nail concerns</p></div>
          </a>
          <a class="card specialty-card" href="search-results.html?specialty=Psychiatrist">
            <div class="icon">🧠</div>
            <div><h3>Psychiatrist</h3><p>Mental health and medication support</p></div>
          </a>
          <a class="card specialty-card" href="search-results.html?specialty=Eye%20Doctor">
            <div class="icon">👁️</div>
            <div><h3>Eye Doctor</h3><p>Vision exams and eye conditions</p></div>
          </a>
          <a class="card specialty-card" href="search-results.html?specialty=Orthopedic%20Surgeon">
            <div class="icon">🦴</div>
            <div><h3>Orthopedic Surgeon</h3><p>Joint, bone, and mobility care</p></div>
          </a>
        </div>
      </div>
    </section>

    <section class="section soft" id="how-it-works">
      <div class="container">
        <h2 class="section-title">How it works</h2>
        <p class="section-copy">From search to booking, MedBook keeps it simple.</p>
        <div class="steps">
          <article class="step">
            <div class="step-num">1</div>
            <h3>Search for a provider</h3>
            <p>Enter a specialty, condition, or doctor name and select your location.</p>
          </article>
          <article class="step">
            <div class="step-num">2</div>
            <h3>Choose a time</h3>
            <p>Compare profiles, read verified reviews, and pick a slot that works for you.</p>
          </article>
          <article class="step">
            <div class="step-num">3</div>
            <h3>Book instantly</h3>
            <p>Confirm your visit online and get reminders so you never miss care.</p>
          </article>
        </div>
      </div>
    </section>

    <section class="section" id="testimonials">
      <div class="container">
        <h2 class="section-title">What patients are saying</h2>
        <p class="section-copy">Real stories from people who booked through MedBook.</p>
        <div class="grid-3">
          <article class="card testimonial">
            <blockquote>“I booked a same-day appointment with a great primary care doctor during my lunch break. MedBook made it incredibly easy.”</blockquote>
            <cite>Priya M. — New York, NY</cite>
          </article>
          <article class="card testimonial">
            <blockquote>“As someone new to the city, MedBook helped me find a primary care doctor who accepts my insurance in under five minutes. Highly recommend!”</blockquote>
            <cite>James T. — Chicago, IL</cite>
          </article>
          <article class="card testimonial">
            <blockquote>“I was dreading finding a new dentist, but the verified reviews on MedBook gave me confidence. My appointment was exactly what I needed.”</blockquote>
            <cite>Laura K. — Austin, TX</cite>
          </article>
        </div>
      </div>
    </section>

    <section class="section">
      <div class="container">
        <div class="app-promo" id="mobile-app-promo">
          <div>
            <h3>Your health, in your pocket</h3>
            <p>Download the MedBook app to search for doctors, manage appointments, and get reminders — all on the go. Available on iOS and Android.</p>
          </div>
          <div class="store-buttons" aria-label="App stores">
            <a href="#" class="store">Download on the App Store</a>
            <a href="#" class="store">Get it on Google Play</a>
          </div>
        </div>
      </div>
    </section>
  </main>

  <footer id="footer">
    <div class="container">
      <div class="footer-grid">
        <section class="footer-col">
          <h4>For Patients</h4>
          <a href="#">Find a Doctor</a>
          <a href="#">Browse Specialties</a>
          <a href="#">Read Reviews</a>
          <a href="#">Insurance Guide</a>
        </section>
        <section class="footer-col">
          <h4>For Providers</h4>
          <a href="#">List Your Practice</a>
          <a href="#">Provider Resources</a>
          <a href="#">Advertise with Us</a>
        </section>
        <section class="footer-col">
          <h4>Company</h4>
          <a href="#">About MedBook</a>
          <a href="#">Careers</a>
          <a href="#">Press</a>
          <a href="#">Blog</a>
          <a href="#">Contact Us</a>
