  <script>
    const suggestionsData = [
      { label: 'Primary Care', type: 'Specialty' },
      { label: 'Dentist', type: 'Specialty' },
      { label: 'Dermatologist', type: 'Specialty' },
      { label: 'Psychiatrist', type: 'Specialty' },
      { label: 'Eye Doctor', type: 'Specialty' },
      { label: 'Orthopedic Surgeon', type: 'Specialty' },
      { label: 'Back pain', type: 'Condition' },
      { label: 'Skin rash', type: 'Condition' },
      { label: 'Anxiety', type: 'Condition' },
      { label: 'Dr. Sarah Kim', type: 'Provider' },
      { label: 'Dr. Anthony Lee', type: 'Provider' }
    ];

    const queryInput = document.getElementById('query');
    const suggestionsBox = document.getElementById('suggestions');

    function renderSuggestions(value) {
      const term = value.trim().toLowerCase();
      if (!term) {
        suggestionsBox.style.display = 'none';
        queryInput.setAttribute('aria-expanded', 'false');
        return;
      }

      const matches = suggestionsData
        .filter(item => item.label.toLowerCase().includes(term))
        .slice(0, 6);

      if (!matches.length) {
        suggestionsBox.style.display = 'none';
        queryInput.setAttribute('aria-expanded', 'false');
        return;
      }

      suggestionsBox.innerHTML = matches
        .map(item => `<button type="button" class="suggestion" role="option"><strong>${item.label}</strong><span>${item.type}</span></button>`)
        .join('');

      suggestionsBox.style.display = 'block';
      queryInput.setAttribute('aria-expanded', 'true');
    }

    queryInput.addEventListener('input', (event) => renderSuggestions(event.target.value));

    suggestionsBox.addEventListener('click', (event) => {
      const btn = event.target.closest('.suggestion');
      if (!btn) return;
      const value = btn.querySelector('strong')?.textContent || '';
      queryInput.value = value;
      suggestionsBox.style.display = 'none';
      queryInput.setAttribute('aria-expanded', 'false');
      queryInput.focus();
    });

    document.addEventListener('click', (event) => {
      if (!event.target.closest('.field')) {
        suggestionsBox.style.display = 'none';
        queryInput.setAttribute('aria-expanded', 'false');
      }
    });

    const menuButton = document.getElementById('mobile-menu-toggle');
    const drawer = document.getElementById('mobile-drawer');
    const backdrop = document.getElementById('menu-backdrop');

    function toggleMenu(forceOpen) {
      const shouldOpen = typeof forceOpen === 'boolean' ? forceOpen : !drawer.classList.contains('open');
      drawer.classList.toggle('open', shouldOpen);
      backdrop.classList.toggle('show', shouldOpen);
      menuButton.setAttribute('aria-expanded', String(shouldOpen));
      drawer.setAttribute('aria-hidden', String(!shouldOpen));
    }

    menuButton.addEventListener('click', () => toggleMenu());
    backdrop.addEventListener('click', () => toggleMenu(false));
    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape') toggleMenu(false);
    });
  </script>
